// RecordReviewAttestation appends an immutable decision for one sealed bundle.
func (s Store) RecordReviewAttestation(att ReviewAttestation, now time.Time) (ReviewAttestation, error) {
	var result ReviewAttestation
	err := s.withReviewAttestationWriteGuard("review.attestation.record", att, func(guarded Store) error {
		var err error
		result, err = guarded.recordReviewAttestation(att, now, false)
		return err
	})
	return result, err
}

func (s Store) recordReviewAttestation(att ReviewAttestation, now time.Time, signed bool) (ReviewAttestation, error) {
	bundle, err := s.LoadReviewBundle(att.BundleID)
	if err != nil {
		return ReviewAttestation{}, err
	}
	policy, _, err := s.loadReviewPolicy()
	if err != nil {
		return ReviewAttestation{}, err
	}
	if policy.RequireSignedAttestations && !signed {
		return ReviewAttestation{}, fmt.Errorf("pose: review policy requires a trusted signed attestation envelope")
	}
	att, err = completeReviewAttestation(bundle, att, now)
	if err != nil {
		return ReviewAttestation{}, err
	}
	// The approval preflight runs here, in the one writer every channel shares,
	// before anything is written: an approval the verifier would reject is
	// refused, not recorded and rejected later (spec
	// pose-review-approval-domain-preflight).
	if blockers := s.reviewApprovalAdmissionBlockers(bundle, att, now); len(blockers) > 0 {
		return ReviewAttestation{}, &ReviewApprovalRefusal{BundleID: bundle.BundleID, Blockers: blockers}
	}
